(()=>{'use strict';const root=document.querySelector('.support-content');if(!root)return;
 const list=root.querySelector('#private-question-list'),form=root.querySelector('#support-question-form'),status=root.querySelector('#support-form-status'),submit=form?.querySelector('[type=submit]');let available=false;
 const text=(tag,value,cls)=>{const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e;};
 const examples=[
 {id:'example-1',demo:true,topic:'예약·내원',author:'김**',date:'2026-11-19',answered:false,subject:'토요일 진료 문의드립니다. (예시)',message:'토요일에 처음 방문하려고 합니다. 방문 전에 예약이 필요한지 궁금합니다.',answer:''},
 {id:'example-2',demo:true,topic:'노안·백내장·인공수정체',author:'이**',date:'2026-11-18',answered:true,subject:'백내장 검사 준비사항이 궁금합니다. (예시)',message:'백내장 검사를 받아보고 싶습니다. 내원할 때 준비할 것이 있을까요?',answer:'안녕하세요. 사용 중인 안경과 복용약 정보, 이전 검사 자료가 있다면 준비해 주세요. 검사 일정과 준비사항은 051-325-1919로 문의해 주시면 안내해 드리겠습니다.'},
 {id:'example-3',demo:true,topic:'소아안과·드림렌즈',author:'박**',date:'2026-11-17',answered:true,subject:'아이 드림렌즈 상담을 받고 싶습니다. (예시)',message:'아이의 드림렌즈 착용 가능 여부를 상담하고 싶습니다. 예약은 어떻게 하면 되나요?',answer:'안녕하세요. 드림렌즈 상담 및 검사 일정은 병원으로 전화해 확인해 주세요. 아이의 눈 상태를 검사한 뒤 착용 가능 여부와 관리 방법을 안내해 드립니다.'}
 ];
 async function call(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:{Accept:'application/json',...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(10000)});let d;try{d=await r.json();}catch{throw Error('상담 게시판 서버 연결을 준비 중입니다.');}if(!r.ok)throw Error(d.error||'요청을 처리하지 못했습니다.');return d;}
 function render(items){if(!list)return;list.replaceChildren();if(!items.length)items=examples;if(items.some(item=>item.demo))list.append(text('p','아래는 화면 확인용 예시입니다. 예시 비밀번호: 1234','support-board-note'));
 items.forEach(item=>{const row=document.createElement('details');row.className='support-faq-item private-board-row';const summary=document.createElement('summary');summary.append(text('span','🔒','private-lock'),text('span',(item.demo?'[예시] ':'')+item.topic+' 상담 · 비밀글','private-row-title'),text('small',item.author+' · '+item.date),text('b',item.answered?'답변완료':'답변대기','private-row-status'));const box=document.createElement('div');box.className='private-read-box';const unlock=document.createElement('form'),label=text('label','작성 시 설정한 비밀번호'),input=document.createElement('input');input.type='password';input.autocomplete='current-password';input.required=true;input.maxLength=128;input.setAttribute('aria-label','비밀글 비밀번호');if(item.demo)input.placeholder='예시 비밀번호: 1234';const button=text('button','글 확인');button.type='submit';button.className='support-button';label.append(input);const feedback=text('p','');feedback.setAttribute('role','status');unlock.append(label,button,feedback);box.append(unlock);row.append(summary,box);list.append(row);
 unlock.addEventListener('submit',async event=>{event.preventDefault();button.disabled=true;try{if(item.demo&&input.value!=='1234')throw Error('예시 비밀번호는 1234입니다.');const d=item.demo?item:await call('/api/inquiries/'+encodeURIComponent(item.id)+'/read',{password:input.value});box.replaceChildren(text('h3',d.subject),text('p',d.message,'private-message'),text('strong',d.answer?'주례성모안과 답변':'답변대기'),text('p',d.answer||'관리자가 확인 후 답변드립니다.','private-message'));input.value='';}catch(error){feedback.textContent=error.message;}finally{button.disabled=false;}});
 });}
 async function load(){try{const d=await call('/api/inquiries');available=true;if(submit)submit.disabled=false;render(d.items);}catch(error){available=false;if(submit)submit.disabled=true;if(list)render(examples);if(status)status.textContent='현재 서버가 연결되지 않아 상담을 등록할 수 없습니다. 작성 내용은 자동 저장되지 않습니다.';}}
 if(form)form.addEventListener('submit',async event=>{event.preventDefault();if(!available||!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));if(d.password!==d.passwordConfirm){status.textContent='비밀번호 확인이 일치하지 않습니다.';return;}submit.disabled=true;status.textContent='상담을 등록하고 있습니다.';try{await call('/api/inquiries',{...d,consent:d.consent==='on'});form.reset();location.href='customer-center.html?registered=1#question-board';}catch(error){status.textContent=error.message;submit.disabled=false;}});
 root.querySelectorAll('[data-faq-filter]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-faq-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelectorAll('[data-faq-category]').forEach(row=>{row.hidden=button.dataset.faqFilter!=='전체'&&row.dataset.faqCategory!==button.dataset.faqFilter;});}));
 if(new URLSearchParams(location.search).get('registered')==='1'&&list){const notice=text('p','상담이 등록되었습니다. 설정한 비밀번호로 질문과 답변을 확인해 주세요.','support-success');notice.setAttribute('role','status');list.before(notice);}if(list||form)load();
})();
